{['buyers','rfqs','quotes','suppliers'].includes(page)&&<section className="panel"><div className="section-head"><h3>{page==='buyers'?(showArchivedBuyers?'Archived buyers':'Active buyers'):models[page].title} · {page==='buyers'?filtered('buyers',showArchivedBuyers).length:filtered(page).length}</h3>{page!=='buyers'&&toolbar(page)}{page==='buyers'&&!showArchivedBuyers&&toolbar('buyers')}</div>{page==='buyers'&&<><div className="buyer-view-tabs" role="group" aria-label="Buyer CRM views"><button type="button" className={!showArchivedBuyers?'active':'secondary'} aria-pressed={!showArchivedBuyers} onClick={()=>setShowArchivedBuyers(false)}>Active buyers ({all('buyers').filter(b=>!isArchivedBuyer(b)).length})</button><button type="button" className={showArchivedBuyers?'active':'secondary'} aria-pressed={showArchivedBuyers} onClick={()=>setShowArchivedBuyers(true)}>Archived buyers ({all('buyers').filter(isArchivedBuyer).length})</button></div><p className="buyer-list-note">{showArchivedBuyers?'Archived buyers are stored safely in Supabase. Open a record and click Restore buyer to return it to active CRM.':'Archiving hides a buyer from active lists, without deleting research, messages, quotations or orders.'}</p></>}{table(page,page==='buyers'?filtered('buyers',showArchivedBuyers):undefined)}</section>}
