{page==='inventory'&&<><div className="note">Create a lot, record a receipt, then release quality before allocating stock. Available kg = on-hand kg − active reservations.</div>{section('inventory')}{canReserveStock(profile.role)&&<button className="mb" onClick={()=>op('Reserve stock against an order','inventory_id! order_id! quantity_kg!',v=>rpc('reserve_stock',{lot:v.inventory_id,oid:v.order_id,qty:Number(v.quantity_kg)}))}>Reserve stock</button>}{section('reservations')}{section('stock_movements')}{section('temperature_logs')}{section('products')}</>}
